import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"会话管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sessions.md","filePath":"guide/sessions.md","lastUpdated":null}'),l={name:"guide/sessions.md"};function i(c,e,s,r,n,h){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h1><p>会话以 append-only JSONL 落盘，是 gsh 的第一公民。</p><h2 id="恢复-分叉" tabindex="-1">恢复 / 分叉 <a class="header-anchor" href="#恢复-分叉" aria-label="Permalink to &quot;恢复 / 分叉&quot;">​</a></h2><ul><li><code>-s &lt;id&gt;</code>：进入终端 UI 并定位到该会话，回放历史后继续提问。</li><li><code>--fork &lt;id&gt;</code>：以某会话为蓝本复制一份新会话后进入（原会话不受影响）。</li><li>终端内 <code>Ctrl+P</code> 打开会话列表，↑/↓ 选择，Enter 打开，d 删除。</li></ul><h2 id="回放-分享" tabindex="-1">回放 / 分享 <a class="header-anchor" href="#回放-分享" aria-label="Permalink to &quot;回放 / 分享&quot;">​</a></h2><ul><li><code>-replay &lt;id&gt;</code>：在终端打印该会话的 Trajectory 文本（用户块 / 助手 / 工具行 + diff）后退出，不依赖 LLM。</li><li><code>-replay &lt;id&gt; -w</code>：打印 Web 只读分享链接 <code>https://&lt;host&gt;/#/share/&lt;id&gt;</code>，对方在浏览器打开即可只读查看（对话 + 轨迹）。</li></ul><div class="warning custom-block"><p class="custom-block-title">分享链接域名</p><p><code>-replay -w</code> 默认打印的 <code>&lt;host&gt;</code> 来自 Web UI 自托管的访问地址，需用 <code>-web-host</code> 显式传入。文档站的 <code>gsh.zgric.top</code> 与 Web UI 自托管域名应分开（例如 Web UI 用 <code>gsh-app.zgric.top</code> 子域），避免端口/路径冲突。</p></div><h2 id="只读浏览" tabindex="-1">只读浏览 <a class="header-anchor" href="#只读浏览" aria-label="Permalink to &quot;只读浏览&quot;">​</a></h2><ul><li><code>-view &lt;id&gt;</code> 或会话内 <code>/readonly</code>：进入只读模式，可滚动、可切会话，但禁止发送。</li></ul><h2 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h2><ul><li><code>/export</code> 或 <code>Ctrl+E</code>：把当前会话导出为 Markdown 文件（<code>gsh-session-&lt;id&gt;.md</code>），落盘到当前工作目录，便于归档或分享。</li></ul>',11)])])}const _=o(l,[["render",i]]);export{u as __pageData,_ as default};
